8	} from 'lucide-react';
9	import { motion } from 'framer-motion';
10	import { Button, Select } from '@/components/ui-custom';
11	import { useCreateQuote } from '@/hooks/use-quotes';
12	import { useToast } from '@/hooks/use-toast';
13	import jsPDF from 'jspdf';
14	
15	// === CONSTANTS & TYPES ===
16	
