42	      yearly: { year1: 55.00, year2plus: 68.70 }
43	    }
44	  }
45	};
46	
47	const IMPLEMENTATIONS = {
48	  US: {
49	    none: { label: 'None (Self-Service)', hours: 0, price: 0 },
50	    express: { label: 'Express (4h)', hours: 4, price: 580 },
51	    starter: { label: 'Starter (25h)', hours: 25, price: 3600 },
52	    basic: { label: 'Basic (50h)', hours: 50, price: 7000 },
53	    standard: { label: 'Standard (100h)', hours: 100, price: 12500 },
54	    custom: { label: 'Custom (200h)', hours: 200, price: 25000 }
55	  },
56	  CA: {
57	    none: { label: 'None (Self-Service)', hours: 0, price: 0 },
58	    starter: { label: 'Starter (4h)', hours: 4, price: 850 },
59	    basic: { label: 'Basic (25h)', hours: 25, price: 5250 },
60	    standard: { label: 'Standard (50h)', hours: 50, price: 10300 },
61	    custom: { label: 'Custom (100h)', hours: 100, price: 18250 },
62	    pro: { label: 'Pro (200h)', hours: 200, price: 36500 }
63	  }
64	};
65	
66	// Odoo SH Pricing (per country)
67	const ODOO_SH_PRICING = {
68	  US: {
69	    shared: {
70	      yearly: { worker: 57.60, storage: 0.20, staging: 14.40, base: 0 },
71	      monthly: { worker: 72.00, storage: 0.25, staging: 18.00, base: 0 },
72	      limits: { workerMin: 1, workerMax: 8, storageMin: 1, storageMax: 512, stagingMin: 0, stagingMax: 20 }
73	    },
74	    dedicated: {
75	      yearly: { worker: 57.60, storage: 0.20, staging: 14.40, base: 480.00 },
76	      monthly: { worker: 72.00, storage: 0.25, staging: 18.00, base: 600.00 },
77	      limits: { workerMin: 4, workerMax: 256, storageMin: 1, storageMax: 4096, stagingMin: 0, stagingMax: 20 }
78	    }
79	  },
80	  CA: {
81	    shared: {
82	      yearly: { worker: 108.00 * 0.80, storage: 0.32, staging: 21.60, base: 0 },
83	      monthly: { worker: 108.00, storage: 0.40, staging: 27.00, base: 0 },
84	      limits: { workerMin: 1, workerMax: 8, storageMin: 1, storageMax: 512, stagingMin: 0, stagingMax: 20 }
85	    },
86	    dedicated: {
87	      yearly: { worker: 108.00 * 0.80, storage: 0.32, staging: 21.60, base: 653.00 },
88	      monthly: { worker: 108.00, storage: 0.40, staging: 27.00, base: 816.00 },
89	      limits: { workerMin: 4, workerMax: 256, storageMin: 1, storageMax: 4096, stagingMin: 0, stagingMax: 20 }
90	    }
91	  }
92	};
93	
94	// Catalyst Finance APR range (Burlington, ON Canada)
95	const CATALYST_APR_LOW = 0.06;   // 6% best rate
96	const CATALYST_APR_HIGH = 0.13;  // 13% standard rate
97	
98	// Standard amortization (PMT) formula
99	// Monthly Payment = P × r(1+r)^n / ((1+r)^n − 1)
100	function pmtCalc(principal: number, annualRate: number, months: number): number {
101	  if (principal <= 0 || months <= 0) return 0;
102	  const r = annualRate / 12;
103	  return (principal * r * Math.pow(1 + r, months)) / (Math.pow(1 + r, months) - 1);
104	}
105	
106	// Calculate monthly financing payment using APR-based amortization
107	function calculateFinancingPayment(
108	  totalAmount: number,
109	  termKey: string
110	): { low: number; high: number } {
111	  if (totalAmount <= 0) return { low: 0, high: 0 };
112	
113	  const years = parseInt(termKey.replace('year', ''));
114	  if (!years || years <= 0) return { low: 0, high: 0 };
115	  const months = years * 12;
116	
117	  return {
118	    low:  pmtCalc(totalAmount, CATALYST_APR_LOW,  months),
119	    high: pmtCalc(totalAmount, CATALYST_APR_HIGH, months),
120	  };
121	}
122	
123	type TermKey = 'monthly' | '1year' | '2year' | '3year' | '4year' | '5year';
124	type ShHostingType = 'shared' | 'dedicated';
125	
126	interface TermDiscounts {
127	  [key: string]: { plan: number; impl: number };
128	}
129	
130	interface SelectedTerms {
131	  [key: string]: boolean;
132	}
133	
134	// Odoo wordmark logo — matches odoo.com visual identity
135	function OdooLogo() {
136	  return (
137	    <div className="flex items-center gap-2.5">
138	      {/* Odoo brand mark: three interlocking circles */}
139	      <svg width="38" height="20" viewBox="0 0 38 20" fill="none" xmlns="http://www.w3.org/2000/svg">
140	        <circle cx="10" cy="10" r="9" fill="#714B67" />
141	        <circle cx="10" cy="10" r="4.5" fill="white" />
142	        <circle cx="26" cy="10" r="9" fill="#714B67" />
143	        <circle cx="26" cy="10" r="4.5" fill="white" />
144	      </svg>
145	      {/* Wordmark */}
146	      <span style={{
147	        fontFamily: '"Roboto", "Inter", sans-serif',
148	        fontWeight: 900,
149	        fontSize: '22px',
150	        color: '#714B67',
151	        letterSpacing: '-0.5px',
152	        lineHeight: 1,
153	      }}>
154	        odoo
155	      </span>
156	    </div>
157	  );
158	}
159	
160	export default function Calculator() {
161	  const { toast } = useToast();
162	  const createQuote = useCreateQuote();
163	
164	  // State
165	  const [showPayoutView, setShowPayoutView] = useState(false);
166	  const [country, setCountry] = useState<Country>('US');
167	  const [users, setUsers] = useState(10);
168	  const [plan, setPlan] = useState<'standard' | 'custom'>('standard');
169	  const [implementation, setImplementation] = useState<string>('none');
170	  const [implMultiplier, setImplMultiplier] = useState<number>(1);
171	
172	  // Odoo SH State
173	  const [shEnabled, setShEnabled] = useState(false);
174	  const [shHostingType, setShHostingType] = useState<ShHostingType>('shared');
175	  const [shWorkers, setShWorkers] = useState(1);
176	  const [shStorage, setShStorage] = useState(1);
177	  const [shStaging, setShStaging] = useState(0);
178	
179	  const [termDiscounts, setTermDiscounts] = useState<TermDiscounts>({
180	    monthly: { plan: 0, impl: 0 },
181	    '1year': { plan: 0, impl: 0 },
182	    '2year': { plan: 0, impl: 0 },
183	    '3year': { plan: 0, impl: 0 },
184	    '4year': { plan: 0, impl: 0 },
185	    '5year': { plan: 0, impl: 0 }
186	  });
187	
188	  const [selectedTerms, setSelectedTerms] = useState<SelectedTerms>({
189	    monthly: true,
190	    '1year': false,
191	    '2year': false,
192	    '3year': false,
193	    '4year': false,
194	    '5year': false
195	  });
196	
197	  // Get current pricing based on country
198	  const currentPricing = PRICING[country];
199	  const currentImplementations = IMPLEMENTATIONS[country];
200	  const countryConfig = COUNTRY_CONFIG[country];
201	
202	  // Format currency based on country (2 decimal places for precision)
203	  const formatCurrency = (amount: number) => {
204	    return new Intl.NumberFormat('en-US', {
205	      style: 'currency',
206	      currency: countryConfig.currency,
207	      minimumFractionDigits: 2,
208	      maximumFractionDigits: 2,
209	    }).format(amount);
210	  };
211	
212	  // Reset implementation and SH when country changes
213	  const handleCountryChange = (newCountry: Country) => {
214	    setCountry(newCountry);
215	    setImplementation('none');
216	  };
217	
218	  // Get SH limits based on hosting type and country
219	  const shLimits = ODOO_SH_PRICING[country][shHostingType].limits;
220	
221	  // Calculate SH monthly cost (aligns with term type: monthly quote = monthly SH, annual quotes = annual SH)
222	  const calculateShMonthlyCost = (isAnnual: boolean) => {
223	    if (!shEnabled) return 0;
224	    const pricing = isAnnual ? ODOO_SH_PRICING[country][shHostingType].yearly : ODOO_SH_PRICING[country][shHostingType].monthly;
225	    const workerCost = shWorkers * pricing.worker;
226	    const storageCost = shStorage * pricing.storage;
227	    const stagingCost = shStaging * pricing.staging;
228	    const baseCost = pricing.base;
229	    return baseCost + workerCost + storageCost + stagingCost;
230	  };
231	
232	  // Calculation Logic
233	  const calculateTermQuote = (termKey: TermKey, planDiscount: number, implDiscount: number) => {
234	    const isMonthly = termKey === 'monthly';
235	    const years = isMonthly ? 1 : parseInt(termKey.replace('year', ''));
236	    const months = isMonthly ? 1 : years * 12;
237	
238	    // Get pricing rates
239	    const monthlyPlanYear1 = currentPricing[plan].monthly.year1;
240	    const monthlyPlanYear2Plus = currentPricing[plan].monthly.year2plus;
241	    const yearlyPlanYear1 = currentPricing[plan].yearly.year1;
242	    const yearlyPlanYear2Plus = currentPricing[plan].yearly.year2plus;
243	
244	    // Calculate software cost based on term type
245	    let totalSoftwareCost = 0;
246	    let softwareCostBeforeDiscount = 0;
247	    
248	    if (isMonthly) {
249	      // Monthly: use monthly rates
250	      // Year 1 at year1 rate (no discount applies to year 1)
251	      const year1Cost = users * monthlyPlanYear1 * 1;
252	      // Plan discount only applies to Year 2+ pricing, but monthly is per-month
253	      // So no discount applies to the monthly quote (it's just 1 month at a time)
254	      softwareCostBeforeDiscount = year1Cost;
255	      totalSoftwareCost = year1Cost; // No plan discount on monthly Year 1 rate
256	    } else {
257	      // Yearly terms:
258	      // Step 1: Calculate the full term cost with ALL years at Year 2+ rate
259	      const fullTermAtYear2Rate = users * yearlyPlanYear2Plus * 12 * years;
260	      
261	      // Step 2: Apply plan discount to the ENTIRE term (not just Year 2+)
262	      const planDiscountAmount = fullTermAtYear2Rate * (planDiscount / 100);
263	      
264	      // Step 3: Subtract Year 1 benefit (year1 rate is lower than year2+ rate)
265	      const year1Benefit = users * (yearlyPlanYear2Plus - yearlyPlanYear1) * 12;
266	      
267	      // softwareCostBeforeDiscount = natural price (all years at year2+ minus year1 benefit)
268	      softwareCostBeforeDiscount = fullTermAtYear2Rate - year1Benefit;
269	      // totalSoftwareCost = apply plan % discount to full year2+ baseline, then subtract year1 benefit
270	      totalSoftwareCost = fullTermAtYear2Rate - planDiscountAmount - year1Benefit;
271	    }
272	
273	    // Implementation cost
274	    const implData = currentImplementations[implementation as keyof typeof currentImplementations];
275	    const implCostBeforeDiscount = (implData?.price || 0) * implMultiplier;
276	    const implementationCost = implCostBeforeDiscount * (1 - implDiscount / 100);
277	
278	    // Odoo SH cost (no discounts, aligns with term type)
279	    const shMonthlyCost = calculateShMonthlyCost(!isMonthly);
280	    const shTotalCost = shMonthlyCost * months;
281	
282	    const totalCost = totalSoftwareCost + implementationCost + shTotalCost;
283	    const amortizedMonthly = totalCost / months;
284	
285	    // === SAVINGS CALCULATION ===
286	    // Plan savings = (Monthly Year2+ rate - Yearly rate) across term
287	    // Implementation savings = impl price * discount %
288	    // Total savings = Plan savings + Implementation discount savings
289	    let totalSavings = 0;
290	
291	    if (isMonthly) {
292	      // Monthly: savings only come from discounts applied
293	      const planDiscountSavings = softwareCostBeforeDiscount * (planDiscount / 100);
294	      const implDiscountSavings = implCostBeforeDiscount * (implDiscount / 100);
295	      totalSavings = planDiscountSavings + implDiscountSavings;
296	    } else {
297	      // Savings = what they'd pay on full monthly billing vs what they're actually paying
298	      // For 1-year term: no Year 2+ exists, so baseline is Year 1 monthly rate × 12 months only
299	      // For 2+ year terms: customer would hit Year 2+ pricing anyway, so use Year2+ monthly rate × all months
300	      let fullMonthlyTotal: number;
301	      if (years === 1) {
302	        fullMonthlyTotal = users * monthlyPlanYear1 * 12;
303	      } else {
304	        fullMonthlyTotal = users * monthlyPlanYear2Plus * months;
305	      }
306	      
307	      // Implementation discount savings
308	      const implDiscountSavings = implCostBeforeDiscount * (implDiscount / 100);
309	      
310	      // Total savings = (monthly baseline - yearly software cost) + impl discount savings
311	      totalSavings = (fullMonthlyTotal - totalSoftwareCost) + implDiscountSavings;
312	    }
313	    
314	    // Calculate financing estimates using Catalyst Finance APR (only for yearly terms)
315	    let financingLow = 0;
316	    let financingHigh = 0;
317	
318	    if (!isMonthly) {
319	      const financing = calculateFinancingPayment(totalCost, termKey);
320	      financingLow  = financing.low;
321	      financingHigh = financing.high;
322	    }
323	
324	    return {
325	      termLabel: isMonthly ? 'Monthly' : `${years} Year${years > 1 ? 's' : ''}`,
326	      termKey,
327	      years,
328	      totalSoftwareCost,
329	      implementationCost,
330	      shTotalCost,
331	      totalCost,
332	      amortizedMonthly,
333	      totalSavings,
334	      financingLow,
335	      financingHigh,
336	    };
337	  };
338	
339	  const handleSaveQuote = () => {
340	    createQuote.mutate({
341	      users,
342	      plan,
343	      implementation,
344	      termDiscounts,
345	      selectedTerms
346	    }, {
347	      onSuccess: () => {
348	        toast({
349	          title: "Quote Saved",
350	          description: "Your configuration has been saved successfully.",
351	        });
352	      },
353	      onError: (err) => {
354	        toast({
355	          title: "Error",
356	          description: err.message,
357	          variant: "destructive"
358	        });
359	      }
360	    });
361	  };
362	
363	  const activeTerms = Object.keys(selectedTerms).filter(k => selectedTerms[k as TermKey]) as TermKey[];
364	
365	  // Compute all quote data once for active terms
366	  const allQuoteData = activeTerms.map(term => ({
367	    term,
368	    data: calculateTermQuote(term, termDiscounts[term].plan, termDiscounts[term].impl)
369	  }));
370	
371	  // Clean PDF Export with proper table design
372	  const handleExportPDF = () => {
373	    const doc = new jsPDF('portrait');
374	    const pageWidth = doc.internal.pageSize.getWidth();
375	    const margin = 20;
376	
377	    // Use precomputed quote data
378	    const quoteData = allQuoteData.map(({ data }) => data);
379	    
380	    const numTerms = quoteData.length;
381	    if (numTerms === 0) {
382	      toast({
383	        title: "No Terms Selected",
384	        description: "Please select at least one term to export.",
385	        variant: "destructive"
386	      });
387	      return;
388	    }
389	
390	    // Header
391	    doc.setFillColor(113, 75, 103);
392	    doc.rect(0, 0, pageWidth, 3, 'F');
393	    
394	    let y = 22;
395	    
396	    // Title
397	    doc.setTextColor(113, 75, 103);
398	    doc.setFontSize(18);
399	    doc.setFont('helvetica', 'bold');
400	    doc.text('Odoo Quote Comparison', margin, y);
401	    
402	    // Date
403	    doc.setFontSize(9);
404	    doc.setFont('helvetica', 'normal');
405	    doc.setTextColor(130, 130, 130);
406	    doc.text(new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }), pageWidth - margin, y, { align: 'right' });
407	    
408	    y += 12;
409	
