      y += 10;

      [
        { label: `Best Rate (${CATALYST_APR_LOW * 100}% APR)`, key: 'financingLow' as keyof typeof quoteData[0], bold: true },
        { label: `Standard (${CATALYST_APR_HIGH * 100}% APR)`, key: 'financingHigh' as keyof typeof quoteData[0], bold: false },
      ].forEach((row) => {
        doc.setFillColor(239, 246, 255);
        doc.rect(margin, y, tableWidth, rowH, 'F');
        doc.setDrawColor(219, 234, 254);
        doc.setLineWidth(0.25);
        doc.rect(margin, y, tableWidth, rowH);
        drawColSeps(y, rowH);

        doc.setFont('helvetica', row.bold ? 'bold' : 'normal');
        doc.setFontSize(8);
        doc.setTextColor(30, 64, 175);
        doc.text(row.label, margin + 5, y + 7.5);

        quoteData.forEach((data, i) => {
          const colX = margin + labelColWidth + i * termColWidth + termColWidth / 2;
