// ── PDF Export ──
const handleExportPDF = () => {
  const doc = new jsPDF('portrait');
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 18;

  const quoteData = allQuoteData.map(({ data }) => data);

  const numTerms = quoteData.length;
  if (numTerms === 0) {
    toast({
      title: "No Terms Selected",
      description: "Please select at least one term to export.",
      variant: "destructive"
    });
    return;
  }

  // ── Header bar ──
  doc.setFillColor(113, 75, 103);
  doc.rect(0, 0, pageWidth, 38, 'F');

  // Odoo wordmark (bold white)
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(22);
  doc.setTextColor(255, 255, 255);
  doc.text('odoo', margin, 22);

  // Subtitle next to wordmark
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.setTextColor(220, 200, 215);
  doc.text('Enterprise Quote', margin + 32, 22);

  // Right: date
  doc.setFontSize(8);
  doc.setTextColor(220, 200, 215);
  const dateStr = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  doc.text(dateStr, pageWidth - margin, 17, { align: 'right' });

  // Right: title
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(255, 255, 255);
  doc.text('QUOTE COMPARISON', pageWidth - margin, 28, { align: 'right' });

  let y = 52;

  // ── Configuration summary card ──
  doc.setFillColor(248, 246, 244);
  doc.roundedRect(margin, y - 7, pageWidth - margin * 2, 24, 3, 3, 'F');
  doc.setDrawColor(232, 227, 220);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, y - 7, pageWidth - margin * 2, 24, 3, 3, 'S');

