file.content:
  doc.text('Monthly Amortized', margin + 5, y + 7.5);

  doc.setFont('helvetica', 'bold');
  quoteData.forEach((data, i) => {
    const colX = margin + labelColWidth + i * termColWidth + termColWidth / 2;
    doc.setTextColor(113, 75, 103);
    doc.text(formatCurrency(data.amortizedMonthly) + '/mo', colX, y + 7.5, { align: 'center' });
  });

  y += rowH + 10;

  // ── Financing section ──
  if (hasAnyFinancing) {
    doc.setFillColor(30, 58, 95);
    doc.roundedRect(margin, y, tableWidth, 10, 2, 2, 'F');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8);
    doc.setTextColor(255, 255, 255);
    doc.text('CATALYST FINANCE', margin + 5, y + 7);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(147, 197, 253);
    doc.text(`${CATALYST_APR_LOW * 100}–${CATALYST_APR_HIGH * 100}% APR · Monthly Financing Estimates`, pageWidth - margin - 4, y + 7, { align: 'right' });

    y += 10;

    [
      { label: `Best Rate (${CATALYST_APR_LOW * 100}% APR)`, key: 'financingLow', bold: true },
      { label: `Standard (${CATALYST_APR_HIGH * 100}% APR)`, key: 'financingHigh', bold: false },
    ].forEach((row) => {
      doc.setFillColor(239, 246, 255);
      doc.rect(margin, y, tableWidth, rowH, 'F');
      doc.setDrawColor(219, 234, 254);
      doc.setLineWidth(0.25);
      doc.rect(margin, y, tableWidth, rowH);
      drawColSeps(y, rowH);

      doc.setFont('helvetica', row.bold ? 'bold' : 'normal');
      doc.setFontSize(8);
      doc.setTextColor(30, 64, 175);
      doc.text(row.label, margin + 5, y + 7.5);

      quoteData.forEach((data, i) => {
        const colX = margin + labelColWidth + i * termColWidth + termColWidth / 2;
        const val = data[row.key as keyof typeof data] as number;
        if (val > 0) {
          doc.setFont('helvetica', 'normal');
          doc.setTextColor(30, 64, 175);
          doc.text(`${formatCurrency(val)}/mo`, colX, y + 7.5, { align: 'center' });
        } else {
          doc.setTextColor(191, 219, 254);
          doc.text('—', colX, y + 7.5, { align: 'center' });
        }
      });

      y += rowH;
    });
  }

  // ── Footer ──
  doc.setFillColor(113, 75, 103);
  doc.rect(0, pageHeight - 12, pageWidth, 12, 'F');

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7);
  doc.setTextColor(220, 200, 215);
  doc.text('This quote is for estimation purposes only. Final pricing may vary.', margin, pageHeight - 4.5);
  doc.text('Odoo Enterprise Quote Builder', pageWidth - margin, pageHeight - 4.5, { align: 'right' });

  doc.save(`odoo-quote-${new Date().toISOString().split('T')[0]}.pdf`);

  toast({
    title: "PDF Exported",
    description: "Your quote has been saved as a PDF.",
  });
};

const implData = currentImplementations[implementation as keyof typeof currentImplementations];

